using System.Linq;using System.Text;using UnityEditor;using UnityEngine;
public static class AgentInspect{public static string Run(){var sb=new StringBuilder();foreach(var path in System.IO.File.ReadAllLines(System.IO.Path.Combine(Application.dataPath,"../AgentScripts/_bridge/arg.txt"))){var go=AssetDatabase.LoadAssetAtPath<GameObject>(path.Trim());if(!go){sb.AppendLine("missing "+path);continue;}sb.AppendLine("== "+path);foreach(var t in go.GetComponentsInChildren<Transform>(true)){int d=0;for(var p=t;p!=go.transform&&p;p=p.parent)d++;if(d>6)continue;var r=t.GetComponent<Renderer>();sb.AppendLine(new string(' ',d)+t.name+" s="+t.localScale.x.ToString("F2")+(r?" ["+r.GetType().Name+" "+string.Join(",",r.sharedMaterials.Select(m=>m?m.name:"null"))+" b="+r.bounds.size.ToString("F1")+"]":"")+" "+string.Join(",",t.GetComponents<Component>().Where(c=>!(c is Transform)&&!(c is Renderer)).Select(c=>c.GetType().Name)));}}return sb.ToString();}}
